"""Independent data tests; hand-written truths are not generated by the engine."""
from dataclasses import replace
import csv
import hashlib
import json
from pathlib import Path
import random

import pytest

from harmony_bidding.data import generate_synthetic, import_history_csv, load_days, validate_day, write_dataset
from harmony_bidding.schema import Advertiser, DayData, Opportunity, Rules


ROOT = Path(__file__).resolve().parents[1]


def config():
    return {"rules": {"total_slots": 4}, "synthetic": {
        "n": 3, "days": 3, "seed": 37, "base_opportunities": 5,
        "budget_min": 10, "budget_max": 20, "empty_slots": [1], "burst_slots": [2],
    }}


def dataset(tmp_path):
    path = tmp_path / "data"
    days = generate_synthetic(config())
    write_dataset(days, path)
    return path, days


def rewrite_rows(path, mutate):
    with path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        fields, rows = reader.fieldnames, list(reader)
    mutate(rows)
    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)


def test_hand_written_tiny_fixture():
    day, = load_days(ROOT / "fixtures" / "tiny", Rules(total_slots=2), expected_n=3)
    assert [a.advertiser_id for a in day.advertisers] == ["A", "B", "C"]
    assert [a.budget for a in day.advertisers] == [100, 100, 100]
    assert day.slots[0][0].values == (10, 8, 11)
    assert day.slots[0][0].participation_mask == (True, True, True)
    assert day.source_schema_version == "harmony-local-csv-v1"
    assert day.source_fingerprint is None  # hand fixture never supplied a digest
    assert day.slots[1] == ()


def test_synthetic_reproducible_heterogeneous_and_rng_independent():
    first = generate_synthetic(config())
    random.seed(98)
    [random.random() for _ in range(100)]
    assert first == generate_synthetic(config())
    assert all(day.slots[1] == () for day in first)
    assert all(len(day.slots[2]) > len(day.slots[0]) for day in first)
    assert all(len(set(o.values)) == 3 for day in first for slot in day.slots for o in slot)
    assert all(10 <= a.budget <= 20 for day in first for a in day.advertisers)
    assert first[0] != first[1]


def test_default_synthetic_has_72_slots_and_three_dates():
    days = generate_synthetic({})
    assert len(days) == 3
    assert all(len(day.slots) == 72 for day in days)
    assert all(len(day.advertisers) == 4 for day in days)


def test_roundtrip_and_whole_date_splits(tmp_path):
    path, days = dataset(tmp_path)
    assert list(load_days(path, Rules(total_slots=4), expected_n=3)) == days
    partitions = [list(load_days(path, Rules(total_slots=4), split=name)) for name in
                  ("train", "validation", "local_holdout")]
    assert [len(p) for p in partitions] == [1, 1, 1]
    assert [p[0].day_id for p in partitions] == [day.day_id for day in days]
    assert set(p[0].day_id for p in partitions) == set(day.day_id for day in days)
    manifest = json.loads((path / "manifest.json").read_text())
    assert [entry["fingerprint"] for entry in manifest["days"]] == [day.fingerprint for day in days]


def test_original_order_not_id_or_file_order(tmp_path):
    day = DayData("manual", (Advertiser("A", "app", 10),),
                  ((Opportunity("manual", 0, "z", 0, (1.,), (True,)),
                    Opportunity("manual", 0, "a", 1, (2.,), (True,))),))
    path = tmp_path / "ordered"
    write_dataset([day], path)
    rewrite_rows(path / "day_0000" / "opportunities.csv", lambda rows: rows.reverse())
    actual, = load_days(path, Rules(total_slots=1))
    assert [o.opportunity_id for o in actual.slots[0]] == ["z", "a"]
    assert actual == day


@pytest.mark.parametrize("bad", [-1., float("nan"), float("inf"), True])
def test_validate_rejects_bad_values_and_budgets(bad):
    day = DayData("x", (Advertiser("A", "app", 10.),), ((Opportunity("x", 0, "o", 0, (bad,), (True,)),),))
    with pytest.raises(ValueError):
        validate_day(day, Rules(total_slots=1))
    with pytest.raises(ValueError):
        validate_day(replace(day, advertisers=(Advertiser("A", "app", bad),)), Rules(total_slots=1))


def test_budget_precision_is_not_silently_rounded(tmp_path):
    day = DayData("x", (Advertiser("A", "app", 1.001),), ((),))
    with pytest.raises(ValueError, match="precision"):
        validate_day(day, Rules(total_slots=1, money_decimals=2))
    write_dataset([day], tmp_path / "precision")
    with pytest.raises(ValueError, match="precision"):
        list(load_days(tmp_path / "precision", Rules(total_slots=1, money_decimals=2)))


@pytest.mark.parametrize("file,mutation,pattern", [
    ("advertisers.csv", lambda rows: rows.append(dict(rows[0])), "duplicate advertiser"),
    ("opportunities.csv", lambda rows: rows.append(dict(rows[0])), "duplicate opportunity"),
    ("opportunities.csv", lambda rows: rows[1].update(original_order=rows[0]["original_order"]), "duplicate original_order"),
    ("opportunities.csv", lambda rows: rows[0].update(time_slot="4"), "time_slot out of range"),
    ("opportunities.csv", lambda rows: rows[0].update(time_slot="1.0"), "integer"),
    ("opportunities.csv", lambda rows: rows[0].update(day_id="wrong-date"), "day_id"),
    ("values.csv", lambda rows: rows.append(dict(rows[0])), "duplicate value key"),
    ("values.csv", lambda rows: rows.pop(), "fingerprint mismatch"),
    ("values.csv", lambda rows: rows[0].update(advertiser_id="unknown"), "unknown opportunity/advertiser"),
    ("values.csv", lambda rows: rows[0].update(opportunity_id="unknown"), "unknown opportunity/advertiser"),
    ("values.csv", lambda rows: rows[0].update(day_id="wrong-date"), "day_id"),
    ("values.csv", lambda rows: rows[0].update(estimated_value=""), "missing or excess"),
    ("values.csv", lambda rows: rows[0].update(estimated_value="-1"), "nonnegative"),
    ("values.csv", lambda rows: rows[0].update(estimated_value="nan"), "nonnegative"),
    ("values.csv", lambda rows: rows[0].update(estimated_value="inf"), "nonnegative"),
    ("values.csv", lambda rows: rows[0].update(estimated_value="-1e-1000"), "nonnegative"),
    ("values.csv", lambda rows: rows[0].update(estimated_value="1e-1000"), "underflows"),
    ("advertisers.csv", lambda rows: rows[0].update(budget="1.00000000000000000001"), "precision"),
    ("advertisers.csv", lambda rows: rows[0].update(budget="1.000000000000000000000000000000000000000000000001"), "precision"),
])
def test_csv_corruption_is_rejected(tmp_path, file, mutation, pattern):
    path, _ = dataset(tmp_path)
    rewrite_rows(path / "day_0000" / file, mutation)
    with pytest.raises(ValueError, match=pattern):
        list(load_days(path, Rules(total_slots=4)))


def test_unselected_date_bad_association_is_rejected(tmp_path):
    path, _ = dataset(tmp_path)
    rewrite_rows(path / "day_0002" / "values.csv", lambda rows: rows[0].update(advertiser_id="wrong"))
    with pytest.raises(ValueError, match="unknown opportunity/advertiser"):
        list(load_days(path, Rules(total_slots=4), split="train"))


def test_manifest_count_slot_split_and_path_validation(tmp_path):
    path, _ = dataset(tmp_path)
    with pytest.raises(ValueError, match="advertiser_count"):
        list(load_days(path, Rules(total_slots=4), expected_n=5))
    with pytest.raises(ValueError, match="total_slots"):
        list(load_days(path, Rules(total_slots=72)))
    with pytest.raises(ValueError, match="unknown split"):
        list(load_days(path, Rules(total_slots=4), split="official_hidden"))
    manifest_path = path / "manifest.json"
    manifest = json.loads(manifest_path.read_text())
    manifest["days"][0]["directory"] = "../outside"
    manifest_path.write_text(json.dumps(manifest))
    with pytest.raises(ValueError, match="inside dataset root"):
        list(load_days(path, Rules(total_slots=4)))


def test_no_overwrite_and_duplicate_date(tmp_path):
    path, days = dataset(tmp_path)
    with pytest.raises(FileExistsError):
        write_dataset(days, path)
    with pytest.raises(ValueError, match="duplicate day_id"):
        write_dataset([days[0], days[0]], tmp_path / "duplicate")


