def test_history_column_aliases_keep_original_order_and_date_split(tmp_path):
    advertisers = tmp_path / "source_advertisers.csv"
    opportunities = tmp_path / "source_opportunities.csv"
    values = tmp_path / "source_values.csv"
    advertisers.write_text("date,owner,kind,money,ignored\n2026-01-01,A,app,20,x\n2026-01-02,A,app,30,x\n")
    opportunities.write_text("date,slot,request,sequence\n2026-01-01,0,a,1\n2026-01-01,0,z,0\n2026-01-02,1,q,0\n")
    values.write_text("date,request,owner,estimate\n2026-01-01,a,A,2\n2026-01-01,z,A,1\n2026-01-02,q,A,7\n")
    mapping = {
        "advertisers": {"day_id": "date", "advertiser_id": "owner", "advertiser_type": "kind", "budget": "money"},
        "opportunities": {"day_id": "date", "time_slot": "slot", "opportunity_id": "request", "original_order": "sequence"},
        "values": {"day_id": "date", "opportunity_id": "request", "advertiser_id": "owner", "estimated_value": "estimate"},
    }
    manifest = import_history_csv(advertisers, opportunities, values, tmp_path / "imported", Rules(total_slots=2),
                                  mapping, {"2026-01-01": "train", "2026-01-02": "local_holdout"})
    days = list(load_days(tmp_path / "imported", Rules(total_slots=2), expected_n=1))
    assert manifest["column_mapping"] == mapping
    assert [o.opportunity_id for o in days[0].slots[0]] == ["z", "a"]
    assert [o.values for o in days[0].slots[0]] == [(1.,), (2.,)]
    assert days[1].slots[0] == ()
    assert days[1].slots[1][0].values == (7.,)
    assert [entry["split"] for entry in manifest["days"]] == ["train", "local_holdout"]


def test_history_import_missing_mapping_fails_without_published_manifest(tmp_path):
    source = tmp_path / "unknown.csv"
    source.write_text("date,owner\n2026-01-01,A\n")
    with pytest.raises(ValueError, match="missing mapped columns"):
        import_history_csv(source, source, source, tmp_path / "invalid", Rules(total_slots=2))
    assert not (tmp_path / "invalid" / "manifest.json").exists()


