def test_sparse_v2_roundtrip_preserves_true_zero_absence_and_empty_request(tmp_path):
    advertisers = (Advertiser("A", "app", 20.), Advertiser("B", "shop", 30.))
    requests = (Opportunity("sparse", 0, "real-zero", 0, (0., 0.), (True, False)),
                Opportunity("sparse", 0, "other-zero", 1, (0., 0.), (False, True)),
                Opportunity("sparse", 0, "no-rows", 2, (0., 0.), (False, False)))
    day = DayData("sparse", advertisers, (requests,))
    destination = tmp_path / "sparse"
    write_dataset([day], destination)
    actual, = load_days(destination, Rules(total_slots=1))
    assert actual == day
    assert actual.source_schema_version == "harmony-local-csv-v2"
    assert actual.source_fingerprint == day.fingerprint
    with (destination / "day_0000" / "values.csv").open(newline="") as handle:
        rows = list(csv.DictReader(handle))
    assert [(row["opportunity_id"], row["advertiser_id"], float(row["estimated_value"])) for row in rows] == [
        ("real-zero", "A", 0.), ("other-zero", "B", 0.)]
    changed = replace(day, slots=((replace(requests[0], participation_mask=(False, False)), *requests[1:]),))
    assert changed.fingerprint != day.fingerprint


@pytest.mark.parametrize("mask,values", [
    ((True,), (1., 2.)), ((True, 0), (1., 0.)), ((True, "false"), (1., 0.)),
    ((True, False), (1., 2.)), ((True, False), (1., float("nan"))),
])
def test_internal_mask_is_explicit_and_cannot_hide_invalid_values(mask, values):
    day = DayData("bad", (Advertiser("A", "x", 10.), Advertiser("B", "x", 10.)),
                  ((Opportunity("bad", 0, "r", 0, values, mask),),))
    with pytest.raises(ValueError):
        validate_day(day, Rules(total_slots=1))


def make_legacy_dataset(tmp_path):
    path, days = dataset(tmp_path)
    manifest_path = path / "manifest.json"
    manifest = json.loads(manifest_path.read_text())
    manifest["schema_version"] = "harmony-local-csv-v1"
    for entry, day in zip(manifest["days"], days):
        entry["fingerprint"] = day.legacy_fingerprint
    manifest_path.write_text(json.dumps(manifest), encoding="utf-8")
    return path, days


def test_legacy_v1_full_matrix_is_read_only_and_verifies_old_digest(tmp_path):
    path, days = make_legacy_dataset(tmp_path)
    before = {str(p.relative_to(path)): hashlib.sha256(p.read_bytes()).hexdigest() for p in path.rglob("*") if p.is_file()}
    loaded = list(load_days(path, Rules(total_slots=4)))
    assert loaded == days
    assert all(all(o.participation_mask) for day in loaded for slot in day.slots for o in slot)
    for old, actual in zip(days, loaded):
        assert actual.source_schema_version == "harmony-local-csv-v1"
        assert actual.source_fingerprint == old.legacy_fingerprint
        assert actual.fingerprint != actual.source_fingerprint
    after = {str(p.relative_to(path)): hashlib.sha256(p.read_bytes()).hexdigest() for p in path.rglob("*") if p.is_file()}
    assert before == after


def test_legacy_v1_missing_row_remains_corruption(tmp_path):
    path, _ = make_legacy_dataset(tmp_path)
    rewrite_rows(path / "day_0000" / "values.csv", lambda rows: rows.pop())
    with pytest.raises(ValueError, match="missing estimated_value.*v1"):
        list(load_days(path, Rules(total_slots=4)))


def test_legacy_v1_fingerprint_corruption_is_not_ignored(tmp_path):
    path, _ = make_legacy_dataset(tmp_path)
    rewrite_rows(path / "day_0000" / "values.csv", lambda rows: rows[0].update(estimated_value="999"))
    with pytest.raises(ValueError, match="fingerprint mismatch"):
        list(load_days(path, Rules(total_slots=4)))


def test_cross_date_type_change_writer_rejected_before_output(tmp_path):
    first = DayData("a", (Advertiser("A", "app", 10.),), ((),))
    changed = DayData("b", (Advertiser("A", "shop", 20.),), ((),))
    destination = tmp_path / "type_conflict"
    with pytest.raises(ValueError, match="player_type conflict across dates"):
        write_dataset([first, changed], destination)
    assert not destination.exists()
    allowed = replace(changed, advertisers=(Advertiser("A", "app", 20.),))
    write_dataset([first, allowed], destination)
    assert [day.advertisers[0].budget for day in load_days(destination, Rules(total_slots=1))] == [10, 20]


def test_cross_date_type_change_in_unselected_split_is_rejected_before_first_yield(tmp_path):
    path, _ = dataset(tmp_path)
    rewrite_rows(path / "day_0002" / "advertisers.csv", lambda rows: rows[0].update(advertiser_type="changed"))
    with pytest.raises(ValueError, match="player_type conflict across dates"):
        next(load_days(path, Rules(total_slots=4), split="train"))


def test_history_cross_date_type_conflict_is_rejected_before_output(tmp_path):
    advertisers = tmp_path / "advertisers.csv"
    advertisers.write_text("day_id,advertiser_id,advertiser_type,budget\na,A,app,10\nb,A,shop,20\n")
    opportunities = tmp_path / "opportunities.csv"
    opportunities.write_text("day_id,time_slot,opportunity_id,original_order\n")
    values = tmp_path / "values.csv"
    values.write_text("day_id,opportunity_id,advertiser_id,estimated_value\n")
    destination = tmp_path / "history_conflict"
    with pytest.raises(ValueError, match="player_type conflict across dates"):
        import_history_csv(advertisers, opportunities, values, destination, Rules(total_slots=1))
    assert not destination.exists()


def test_v2_history_import_accepts_sparse_presence(tmp_path):
    advertisers = tmp_path / "advertisers.csv"
    advertisers.write_text("day_id,advertiser_id,advertiser_type,budget\na,A,app,10\na,B,shop,20\n")
    opportunities = tmp_path / "opportunities.csv"
    opportunities.write_text("day_id,time_slot,opportunity_id,original_order\na,0,r,0\n")
    values = tmp_path / "values.csv"
    values.write_text("day_id,opportunity_id,advertiser_id,estimated_value\na,r,A,0\n")
    destination = tmp_path / "history_sparse"
    import_history_csv(advertisers, opportunities, values, destination, Rules(total_slots=1))
    day, = load_days(destination, Rules(total_slots=1))
    assert day.slots[0][0].values == (0., 0.)
    assert day.slots[0][0].participation_mask == (True, False)
